1607 static SmallBitVector getAltInstrMask(ArrayRef<Value *> VL, Type *ScalarTy,
1608                                       unsigned Opcode0, unsigned Opcode1) {
1609   unsigned ScalarTyNumElements = getNumElements(ScalarTy);
1610   SmallBitVector OpcodeMask(VL.size() * ScalarTyNumElements, false);
1611   for (unsigned Lane : seq<unsigned>(VL.size())) {
1612     if (isa<PoisonValue>(VL[Lane]))
1613       continue;
1614     if (cast<Instruction>(VL[Lane])->getOpcode() == Opcode1)
1615       OpcodeMask.set(Lane * ScalarTyNumElements,
1616                      Lane * ScalarTyNumElements + ScalarTyNumElements);
1617   }
1618   return OpcodeMask;
