1621 /// Replicates the given \p Val \p VF times.
1622 static SmallVector<Constant *> replicateMask(ArrayRef<Constant *> Val,
1623                                              unsigned VF) {
1624   assert(none_of(Val, [](Constant *C) { return C->getType()->isVectorTy(); }) &&
1625          "Expected scalar constants.");
1626   SmallVector<Constant *> NewVal(Val.size() * VF);
1627   for (auto [I, V] : enumerate(Val))
1628     std::fill_n(NewVal.begin() + I * VF, VF, V);
1629   return NewVal;
