1643 /// Reorders the list of scalars in accordance with the given \p Mask.
1644 static void reorderScalars(SmallVectorImpl<Value *> &Scalars,
1645                            ArrayRef<int> Mask) {
1646   assert(!Mask.empty() && "Expected non-empty mask.");
1647   SmallVector<Value *> Prev(Scalars.size(),
1648                             PoisonValue::get(Scalars.front()->getType()));
1649   Prev.swap(Scalars);
1650   for (unsigned I = 0, E = Prev.size(); I < E; ++I)
1651     if (Mask[I] != PoisonMaskElem)
1652       Scalars[Mask[I]] = Prev[I];
1653 }
